import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int y;
        int capacity;
        int flow;
        int cost;

        Edge(int y, int capacity, int flow, int cost) {
            this.y = y;
            this.capacity = capacity;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static final long INF64 = (long)1e18;
    static final int MAXN = 1000007;
    static List<Integer>[] graph = new ArrayList[MAXN];
    static List<Edge> edges = new ArrayList<>();
    static long totalCost = 0;
    static long[] distanceArr = new long[MAXN];
    static int[] predecessor = new int[MAXN];
    static int[] edgeIndex = new int[MAXN];
    static int[] inQueue = new int[MAXN];

    static int sourceNode;
    static int sinkNode;

    static int n, m, k, c, d;

    static int normalize(int a) {
        return ((a % MOD) + MOD) % MOD;
    }

    static int multiply(int a, int b) {
        return (int)((a * 1L * b) % MOD);
    }

    static int power(int a, int k) {
        int result = 1;
        while (k > 0) {
            if ((k & 1) == 1) result = multiply(result, a);
            a = multiply(a, a);
            k >>= 1;
        }
        return result;
    }

    static int inverse(int a) {
        int b = power(a, MOD - 2);
        assert multiply(a, b) == 1;
        return b;
    }

    static int residualCap(int x) {
        return edges.get(x).capacity - edges.get(x).flow;
    }

    static void addEdge(int x, int y, int capacity, int cost) {
        graph[x].add(edges.size());
        edges.add(new Edge(y, capacity, 0, cost));
        graph[y].add(edges.size());
        edges.add(new Edge(x, 0, 0, -cost));
    }

    static void augmentFlow() {
        Arrays.fill(distanceArr, INF64);
        Arrays.fill(predecessor, -1);
        Arrays.fill(edgeIndex, -1);
        Arrays.fill(inQueue, 0);
        distanceArr[sourceNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sourceNode);
        inQueue[sourceNode] = 1;
        while (!q.isEmpty()) {
            int k = q.poll();
            inQueue[k] = 0;
            for (int eIdx : graph[k]) {
                if (residualCap(eIdx) == 0) continue;
                int cst = edges.get(eIdx).cost;
                int y = edges.get(eIdx).y;
                if (distanceArr[y] > distanceArr[k] + cst) {
                    distanceArr[y] = distanceArr[k] + cst;
                    predecessor[y] = k;
                    edgeIndex[y] = eIdx;
                    if (inQueue[y] == 0) {
                        inQueue[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int current = sinkNode;
        while (current != sourceNode) {
            int eIdx = edgeIndex[current];
            edges.get(eIdx).flow++;
            edges.get(eIdx ^ 1).flow--;
            current = predecessor[current];
        }
        totalCost += distanceArr[sinkNode];
    }

    static void readInput() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        for (int i = 0; i < MAXN; i++) {
            graph[i] = new ArrayList<>();
        }

        sourceNode = MAXN - 2;
        sinkNode = MAXN - 1;

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            addEdge(sourceNode, x, 1, 0);
        }

        int timeLayers = 101;
        for (int i = 0; i < timeLayers; i++) {
            addEdge(i * n, sinkNode, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int t = 0; t < timeLayers - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
                }
            }
            for (int t = 0; t < timeLayers - 1; t++) {
                for (int j = 0; j < k; j++) {
                    addEdge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < timeLayers - 1; j++) {
                addEdge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            augmentFlow();
        }

        System.out.println(totalCost);
        sc.close();
    }

    public static void main(String[] args) {
        readInput();
    }
}

